const fs = require('node:fs'), path = require('node:path');
const ROOT = process.env.LOBOS_ROOT || path.resolve(__dirname, '..');
const P = path.join(ROOT, 'scripts', 'm0-criteria.json');
if (!fs.existsSync(P)) { console.error('报缺：那判据库逐字不在 ' + P); process.exit(2); }
const d = JSON.parse(fs.readFileSync(P, 'utf8'));
const rows = (d['$hostBoundAuditItems'] || []);
if (!rows.length) { console.error('报缺：那 12 条逐字不在 $hostBoundAuditItems 那一栏'); process.exit(2); }
let bad = 0, miss = 0, done = 0;
const TIERS = ['原生等价', '近似', '不支持', '缺'];
for (const r of rows) {
  const m = r['三格机读'];
  if (!m) { console.error('  [红] ' + r['条目'] + ' 逐字没有那三格机读那一格（=> 而那那一族逐字没有落进可跑的形状）'); bad++; continue; }
  const cells = [m.actual, m.positive, m.negative];
  const names = ['actual', 'positive', 'negative'];
  cells.forEach((v, i) => {
    if (v === '已核') { done++; }
    else if (v === '缺') { miss++; }
    else { console.error('  [红] ' + r['条目'] + ' 的 ' + names[i] + ' 逐字是 ' + JSON.stringify(v) + '（=> 而那取值域逐字只有「已核」与「缺」）'); bad++; }
  });
  const tier = String(r['declared_tier 机读'] || '');
  if (TIERS.indexOf(tier) < 0) {
    console.error('  [红] ' + r['条目'] + ' 的 declared_tier 机读逐字是 ' + JSON.stringify(tier) + '（=> 而那取值域逐字是那四个：' + TIERS.join(' / ') + '）'); bad++;
  }
  const allDone = cells.every(v => v === '已核');
  if (!allDone && tier !== '缺') {
    console.error('  [红] ' + r['条目'] + ' 的三格机读逐字不全「已核」（=> 而那 actual=' + m.actual + ' positive=' + m.positive + ' negative=' + m.negative + '）'
      + '，=> 而而那 declared_tier 机读逐字必须是「缺」、=> 而而那实得 ' + JSON.stringify(tier) + '（=> 而那按 C-05 不许猜填）'); bad++;
  }
  if (allDone && tier === '缺') {
    console.error('  [红] ' + r['条目'] + ' 的三格机读逐字全「已核」、=> 而而那 declared_tier 机读逐字**不该**是「缺」（=> 而那按 R3 那一族逐字该算一档）'); bad++;
  }
  const s = String(r['S 值'] || '').match(/「\*\*(S[123])\*\*」/);
  if (!s) { console.error('  [红] ' + r['条目'] + ' 逐字没有那 S 值那一格（=> 而那它逐字不可机读）'); bad++; }
}
console.log('  那 12 条逐条：三格已核 ' + done + ' 格、缺 ' + miss + ' 格；档位取值域=' + TIERS.join('/') + '；形状不合 ' + bad + ' 处');
if (bad) { console.error('::error title=那 12 条逐条没有落进可跑的形状::' + bad + ' 处不合（=> 而那判据库那一族那一层、=> 而那规范那一层归 04）'); process.exit(1); }
console.log('  => 而那 12 条逐条逐字落进那可跑的形状、=> 而那三格逐条**可机读**、=> 而那 declared_tier 逐字**可机读**');
